-- =====================================================================
--  File 01: Database schema – heavy construction equipment rental (kltn_1)
--  16 tables (15 entities of the ERD + 1 audit table equipment_price_history) + 5 views. Run this file first, then 02_seed_data.sql.
--  Conventions:
--    * Every table has an auto-increment surrogate primary key `id`.
--    * Business document numbers (contract_no, handover_no, return_no, equipment code…)
--      are separate UNIQUE columns generated by the backend, e.g. TH-2026-0001.
--    * Columns ending in _by reference users(id) = who performed the action.
--    * No notification table: notifications are computed from contracts (end_date, status…).
--      Equipment rental history (and the prices applied) comes from contracts + handovers + returns;
--      equipment_price_history only logs price edits (who / when / why) and is not an ERD entity.
-- =====================================================================
SET NAMES utf8mb4;

DROP DATABASE IF EXISTS kltn_1;
CREATE DATABASE kltn_1 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kltn_1;

CREATE TABLE roles (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  code        VARCHAR(10)  NOT NULL UNIQUE,
  name        VARCHAR(50)  NOT NULL,
  description VARCHAR(255),
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE TABLE departments (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  code       VARCHAR(10)  NOT NULL UNIQUE,
  name       VARCHAR(50)  NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE TABLE employees (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  code          VARCHAR(10)  NOT NULL UNIQUE,
  full_name     VARCHAR(50)  NOT NULL,
  gender        ENUM('MALE','FEMALE','OTHER'),
  date_of_birth DATE,
  id_number     VARCHAR(12)  UNIQUE,
  phone         VARCHAR(11),
  email         VARCHAR(100) UNIQUE COMMENT 'Company email, also the login name of the account',
  address       VARCHAR(255),
  avatar_url    VARCHAR(255) NULL COMMENT 'Profile photo',
  department_id INT NOT NULL,
  position      VARCHAR(50),
  hire_date     DATE,
  status        ENUM('WORKING','RESIGNED') NOT NULL DEFAULT 'WORKING',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_emp_dept FOREIGN KEY (department_id) REFERENCES departments(id),
  CONSTRAINT chk_emp_id_number CHECK (id_number REGEXP '^[0-9]{12}$'),
  CONSTRAINT chk_emp_phone     CHECK (phone REGEXP '^0[0-9]{9,10}$'),
  CONSTRAINT chk_emp_hire_date CHECK (hire_date IS NULL OR date_of_birth IS NULL OR hire_date >= date_of_birth)
);

CREATE TABLE users (
  id                   INT AUTO_INCREMENT PRIMARY KEY,
  employee_id          INT NOT NULL UNIQUE COMMENT 'Login name = employees.email (company email)',
  password_hash        CHAR(60)     NOT NULL COMMENT 'bcrypt hash, always 60 characters',
  role_id              INT NOT NULL,
  status               ENUM('ACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE',
  must_change_password BOOLEAN  NOT NULL DEFAULT TRUE,
  failed_login_count   TINYINT  NOT NULL DEFAULT 0,
  locked_until         DATETIME NULL,
  last_login_at        DATETIME NULL,
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_user_emp  FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_user_role FOREIGN KEY (role_id)     REFERENCES roles(id),
  CONSTRAINT chk_user_failed CHECK (failed_login_count BETWEEN 0 AND 5)
);

CREATE TABLE customers (
  id                   INT AUTO_INCREMENT PRIMARY KEY,
  code                 VARCHAR(10)  NOT NULL UNIQUE,
  customer_type        ENUM('COMPANY','INDIVIDUAL') NOT NULL,
  name                 VARCHAR(200) NOT NULL COMMENT 'Company name, or full name for an individual',
  id_number            VARCHAR(14)  NOT NULL UNIQUE COMMENT 'COMPANY: tax code; INDIVIDUAL: citizen ID (CCCD)',
  representative       VARCHAR(50)  NOT NULL COMMENT 'INDIVIDUAL: same as name',
  representative_title VARCHAR(50),
  phone                VARCHAR(11)  NOT NULL,
  email                VARCHAR(100),
  address              VARCHAR(255),
  bank_account         VARCHAR(20),
  bank_name            VARCHAR(100),
  note                 TEXT,
  status               ENUM('ACTIVE','STOPPED') NOT NULL DEFAULT 'ACTIVE' COMMENT 'STOPPED = no new contracts allowed',
  created_by           INT NULL,
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_cus_user FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT chk_cus_identity CHECK (
    (customer_type = 'COMPANY'    AND id_number REGEXP '^[0-9]{10}(-[0-9]{3})?$') OR
    (customer_type = 'INDIVIDUAL' AND id_number REGEXP '^[0-9]{12}$')
  ),
  CONSTRAINT chk_cus_phone CHECK (phone REGEXP '^0[0-9]{9,10}$')
);

CREATE TABLE warehouses (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  code       VARCHAR(10)  NOT NULL UNIQUE,
  name       VARCHAR(100) NOT NULL UNIQUE,
  address    VARCHAR(255) NOT NULL,
  area_m2    DECIMAL(10,2),
  capacity   INT,
  status     ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT chk_wh_area     CHECK (area_m2 IS NULL OR area_m2 > 0),
  CONSTRAINT chk_wh_capacity CHECK (capacity IS NULL OR capacity > 0)
);

-- Two-level equipment categories: group (level 1, parent_id = NULL) -> type (level 2, parent_id = group id).
-- Equipment is always attached to a level-2 type.
CREATE TABLE equipment_categories (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  parent_id   INT NULL COMMENT 'NULL = group (level 1); otherwise = type (level 2) of this group',
  code        VARCHAR(10)  NOT NULL UNIQUE,
  name        VARCHAR(100) NOT NULL UNIQUE,
  description VARCHAR(255),
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_cat_parent FOREIGN KEY (parent_id) REFERENCES equipment_categories(id)
);

CREATE TABLE brands (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  name       VARCHAR(50)  NOT NULL UNIQUE,
  country    VARCHAR(50),
  website    VARCHAR(255),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE TABLE equipments (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  code             VARCHAR(15)  NOT NULL UNIQUE COMMENT 'SKU + yy + mm + 4-digit sequence, e.g. SKU26070001',
  name             VARCHAR(200) NOT NULL COMMENT 'Built by the system: year - brand model - type',
  category_id      INT NOT NULL,
  brand_id         INT NOT NULL,
  model            VARCHAR(50)  NOT NULL,
  serial_number    VARCHAR(50)  NOT NULL UNIQUE,
  engine_number    VARCHAR(50)  UNIQUE,
  manufacture_year SMALLINT NOT NULL,
  item_condition   ENUM('NEW','USED') NOT NULL DEFAULT 'USED',
  origin_country   VARCHAR(50),
  specifications   VARCHAR(500),
  purchase_date    DATE,
  purchase_price   DECIMAL(15,0),
  operating_hours  DECIMAL(10,1) NOT NULL DEFAULT 0,
  hourly_rate      DECIMAL(15,0) NULL,
  daily_rate       DECIMAL(15,0) NULL,
  warehouse_id     INT NULL,
  status           ENUM('AVAILABLE','RESERVED','RENTED','INACTIVE','LIQUIDATED') NOT NULL DEFAULT 'AVAILABLE',
  status_note      VARCHAR(255) NULL COMMENT 'Reason for INACTIVE / LIQUIDATED (current status only)',
  image_url        VARCHAR(255),
  note             TEXT,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_eq_cat   FOREIGN KEY (category_id)  REFERENCES equipment_categories(id),
  CONSTRAINT fk_eq_brand FOREIGN KEY (brand_id)     REFERENCES brands(id),
  CONSTRAINT fk_eq_wh    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id),
  CONSTRAINT chk_eq_rates CHECK ((hourly_rate IS NULL AND daily_rate IS NULL) OR (hourly_rate > 0 AND daily_rate > 0)),
  CONSTRAINT chk_eq_year  CHECK (manufacture_year BETWEEN 1950 AND 2100),
  CONSTRAINT chk_eq_hours CHECK (operating_hours >= 0),
  CONSTRAINT chk_eq_price CHECK (purchase_price IS NULL OR purchase_price >= 0),
  INDEX idx_eq_status (status),
  INDEX idx_eq_cat (category_id)
);

CREATE TABLE equipment_documents (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  equipment_id INT NOT NULL,
  doc_type     ENUM('PHOTO','NAMEPLATE','CUSTOMS','CO','CQ','REGISTRATION','INSPECTION','MANUAL','OTHER') NOT NULL COMMENT 'NAMEPLATE = photo of the nameplate used to read model / serial / engine number',
  doc_number   VARCHAR(50),
  file_url     VARCHAR(255) NOT NULL,
  issued_date  DATE,
  expiry_date  DATE NULL,
  uploaded_by  INT NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_doc_eq   FOREIGN KEY (equipment_id) REFERENCES equipments(id) ON DELETE CASCADE,
  CONSTRAINT fk_doc_user FOREIGN KEY (uploaded_by)  REFERENCES users(id),
  CONSTRAINT chk_doc_dates CHECK (expiry_date IS NULL OR issued_date IS NULL OR expiry_date >= issued_date)
);

-- Audit log of rental price edits (not an ERD entity)
CREATE TABLE equipment_price_history (
  id              INT AUTO_INCREMENT PRIMARY KEY,
  equipment_id    INT NOT NULL,
  old_hourly_rate DECIMAL(15,0) NULL COMMENT 'NULL = first price set',
  old_daily_rate  DECIMAL(15,0) NULL,
  new_hourly_rate DECIMAL(15,0) NOT NULL,
  new_daily_rate  DECIMAL(15,0) NOT NULL,
  reason          VARCHAR(255) NULL,
  changed_by      INT NULL,
  changed_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ph_eq   FOREIGN KEY (equipment_id) REFERENCES equipments(id) ON DELETE CASCADE,
  CONSTRAINT fk_ph_user FOREIGN KEY (changed_by)   REFERENCES users(id),
  INDEX idx_ph_eq_time (equipment_id, changed_at)
);

CREATE TABLE rental_contracts (
  id                   INT AUTO_INCREMENT PRIMARY KEY,
  contract_no          VARCHAR(20)  NOT NULL UNIQUE COMMENT 'e.g. HD-2026-0001 (sequence restarts every year)',
  customer_id          INT NOT NULL,
  delivery_address     VARCHAR(255) NOT NULL COMMENT 'Machine delivery location',
  start_date           DATE NOT NULL,
  end_date             DATE NOT NULL,
  pricing_type         ENUM('HOUR','DAY') NOT NULL,
  subtotal             DECIMAL(15,0) NOT NULL DEFAULT 0,
  transport_fee        DECIMAL(15,0) NOT NULL DEFAULT 0,
  discount_rate        DECIMAL(5,2)  NOT NULL DEFAULT 0,
  discount_amount      DECIMAL(15,0) NOT NULL DEFAULT 0,
  vat_rate             DECIMAL(4,2)  NOT NULL DEFAULT 10.00,
  vat_amount           DECIMAL(15,0) NOT NULL DEFAULT 0,
  total_amount         DECIMAL(15,0) NOT NULL DEFAULT 0,
  deposit_amount       DECIMAL(15,0) NULL,
  deposit_paid_at      DATETIME NULL,
  deposit_confirmed_by INT NULL,
  status               ENUM('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','ACTIVE','COMPLETED','SETTLED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
  submitted_at         DATETIME NULL COMMENT 'Sent for approval (used for approval reminders)',
  reminded_at          DATETIME NULL COMMENT 'Last time staff pressed "Remind approval" (shown in the manager''s notifications)',
  approved_by          INT NULL,
  approved_at          DATETIME NULL,
  reject_reason        VARCHAR(255) NULL,
  cancel_reason        VARCHAR(255) NULL,
  cancelled_by         INT NULL,
  cancelled_at         DATETIME NULL,
  note                 TEXT,
  created_by           INT NOT NULL,
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_rc_cus      FOREIGN KEY (customer_id)          REFERENCES customers(id),
  CONSTRAINT fk_rc_deposit  FOREIGN KEY (deposit_confirmed_by) REFERENCES users(id),
  CONSTRAINT fk_rc_approver FOREIGN KEY (approved_by)          REFERENCES users(id),
  CONSTRAINT fk_rc_creator  FOREIGN KEY (created_by)           REFERENCES users(id),
  CONSTRAINT fk_rc_canceller FOREIGN KEY (cancelled_by) REFERENCES users(id),
  CONSTRAINT chk_rc_dates   CHECK (end_date >= start_date),
  CONSTRAINT chk_rc_rates   CHECK (discount_rate BETWEEN 0 AND 100 AND vat_rate BETWEEN 0 AND 100),
  CONSTRAINT chk_rc_amounts CHECK (subtotal >= 0 AND transport_fee >= 0 AND discount_amount >= 0 AND vat_amount >= 0
                                   AND total_amount >= 0 AND (deposit_amount IS NULL OR deposit_amount >= 0)),
  CONSTRAINT chk_rc_deposit CHECK (status NOT IN ('ACTIVE','COMPLETED','SETTLED') OR (deposit_amount IS NOT NULL AND deposit_paid_at IS NOT NULL)),
  INDEX idx_rc_status_dates (status, start_date, end_date),
  INDEX idx_rc_customer (customer_id)
);

CREATE TABLE contract_details (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  contract_id  INT NOT NULL,
  equipment_id INT NOT NULL,
  unit_price   DECIMAL(15,0) NOT NULL COMMENT 'Price per day or per hour (by contract pricing_type), copied from equipments',
  hourly_rate  DECIMAL(15,0) NOT NULL COMMENT 'Hourly rate copied from equipments, used for overtime fees',
  planned_duration DECIMAL(8,1) NOT NULL COMMENT 'Planned days or hours',
  amount       DECIMAL(15,0) NOT NULL,
  status       ENUM('PENDING','HANDED_OVER','RETURNED') NOT NULL DEFAULT 'PENDING',
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_cd_contract FOREIGN KEY (contract_id)  REFERENCES rental_contracts(id) ON DELETE CASCADE,
  CONSTRAINT fk_cd_eq       FOREIGN KEY (equipment_id) REFERENCES equipments(id),
  CONSTRAINT uq_cd UNIQUE (contract_id, equipment_id),
  CONSTRAINT chk_cd_values CHECK (unit_price > 0 AND hourly_rate > 0 AND planned_duration > 0 AND amount >= 0),
  INDEX idx_cd_eq (equipment_id)
);

CREATE TABLE handovers (
  id                 INT AUTO_INCREMENT PRIMARY KEY,
  handover_no        VARCHAR(20) NOT NULL UNIQUE COMMENT 'e.g. BG-2026-0001 (sequence restarts every year)',
  contract_detail_id INT NOT NULL UNIQUE,
  handover_at        DATETIME NOT NULL,
  from_warehouse_id  INT NULL,
  operating_hours    DECIMAL(10,1) NOT NULL,
  meter_photo_url    VARCHAR(255) NULL COMMENT 'Photo of the hour meter at handover',
  fuel_level         TINYINT,
  condition_note     TEXT,
  accessories        VARCHAR(500),
  receiver_name      VARCHAR(50)  NOT NULL,
  receiver_phone     VARCHAR(11),
  handed_by          INT NOT NULL,
  created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_ho_cd   FOREIGN KEY (contract_detail_id) REFERENCES contract_details(id),
  CONSTRAINT fk_ho_wh   FOREIGN KEY (from_warehouse_id)  REFERENCES warehouses(id),
  CONSTRAINT fk_ho_user FOREIGN KEY (handed_by)          REFERENCES users(id),
  CONSTRAINT chk_ho_fuel CHECK (fuel_level BETWEEN 0 AND 100),
  CONSTRAINT chk_ho_hours CHECK (operating_hours >= 0)
);

CREATE TABLE equipment_returns (
  id                  INT AUTO_INCREMENT PRIMARY KEY,
  return_no           VARCHAR(20) NOT NULL UNIQUE COMMENT 'e.g. TH-2026-0001 (sequence restarts every year)',
  contract_detail_id  INT NOT NULL UNIQUE,
  returned_at         DATETIME NOT NULL,
  to_warehouse_id     INT NOT NULL,
  operating_hours     DECIMAL(10,1) NOT NULL,
  meter_photo_url     VARCHAR(255) NULL COMMENT 'Photo of the hour meter at return',
  fuel_level          TINYINT,
  condition_note      TEXT,
  is_damaged          BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'TRUE -> equipment becomes INACTIVE',
  damage_description  TEXT NULL,
  rental_amount       DECIMAL(15,0) NOT NULL,
  late_days           INT NOT NULL DEFAULT 0,
  late_fee            DECIMAL(15,0) NOT NULL DEFAULT 0 COMMENT 'Not charged (always 0): hours run on late days are billed as overtime',
  overtime_hours      DECIMAL(10,1) NOT NULL DEFAULT 0 COMMENT 'Hours above 8 h/day (daily pricing)',
  overtime_fee        DECIMAL(15,0) NOT NULL DEFAULT 0,
  compensation_amount DECIMAL(15,0) NOT NULL DEFAULT 0,
  received_by         INT NOT NULL,
  created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ret_cd   FOREIGN KEY (contract_detail_id) REFERENCES contract_details(id),
  CONSTRAINT fk_ret_wh   FOREIGN KEY (to_warehouse_id)    REFERENCES warehouses(id),
  CONSTRAINT fk_ret_user FOREIGN KEY (received_by)        REFERENCES users(id),
  CONSTRAINT chk_ret_fuel CHECK (fuel_level BETWEEN 0 AND 100),
  CONSTRAINT chk_ret_values CHECK (operating_hours >= 0 AND rental_amount >= 0 AND late_days >= 0 AND late_fee >= 0
                                   AND overtime_hours >= 0 AND overtime_fee >= 0 AND compensation_amount >= 0)
);

CREATE TABLE settlements (
  id                 INT AUTO_INCREMENT PRIMARY KEY,
  contract_id        INT NOT NULL UNIQUE,
  rental_total       DECIMAL(15,0) NOT NULL,
  late_fee_total     DECIMAL(15,0) NOT NULL DEFAULT 0,
  overtime_fee_total DECIMAL(15,0) NOT NULL DEFAULT 0,
  compensation_total DECIMAL(15,0) NOT NULL DEFAULT 0,
  vat_amount         DECIMAL(15,0) NOT NULL DEFAULT 0,
  deposit_amount     DECIMAL(15,0) NOT NULL,
  amount_due         DECIMAL(15,0) NOT NULL COMMENT 'Negative = refund the deposit surplus',
  paid_amount        DECIMAL(15,0) NOT NULL DEFAULT 0,
  payment_status     ENUM('UNPAID','PARTIAL','PAID','REFUNDED') NOT NULL DEFAULT 'UNPAID',
  confirmed_by       INT NULL,
  confirmed_at       DATETIME NULL,
  note               VARCHAR(255),
  created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_st_contract FOREIGN KEY (contract_id)  REFERENCES rental_contracts(id),
  CONSTRAINT fk_st_user     FOREIGN KEY (confirmed_by) REFERENCES users(id),
  CONSTRAINT chk_st_values CHECK (rental_total >= 0 AND late_fee_total >= 0 AND overtime_fee_total >= 0
                                  AND compensation_total >= 0 AND vat_amount >= 0 AND deposit_amount >= 0 AND paid_amount >= 0),
  INDEX idx_st_confirmed (confirmed_at),
  INDEX idx_st_payment (payment_status)
);

-- Inventory report by group -> type (only types that have equipment)
CREATE VIEW v_report_equipment_status AS
SELECT g.id AS group_id, g.code AS group_code, g.name AS group_name,
       c.id AS category_id, c.code AS category_code, c.name AS category_name,
       COUNT(e.id)                        AS total,
       SUM(e.status = 'AVAILABLE')        AS available,
       SUM(e.status = 'RESERVED')         AS reserved,
       SUM(e.status = 'RENTED')           AS rented,
       SUM(e.status = 'INACTIVE')         AS inactive
FROM equipment_categories c
JOIN equipment_categories g ON g.id = c.parent_id
JOIN equipments e ON e.category_id = c.id AND e.status <> 'LIQUIDATED'
GROUP BY g.id, g.code, g.name, c.id, c.code, c.name;

-- Monthly revenue from confirmed settlements
CREATE VIEW v_report_revenue_monthly AS
SELECT DATE_FORMAT(s.confirmed_at, '%Y-%m')                          AS period,
       COUNT(*)                                                     AS contracts,
       SUM(s.rental_total)                                          AS rental_revenue,
       SUM(s.late_fee_total + s.overtime_fee_total)                 AS extra_fees,
       SUM(s.compensation_total)                                    AS compensation,
       SUM(s.rental_total + s.late_fee_total + s.overtime_fee_total + s.compensation_total) AS revenue,
       SUM(s.vat_amount)                                            AS vat
FROM settlements s
WHERE s.confirmed_at IS NOT NULL
GROUP BY DATE_FORMAT(s.confirmed_at, '%Y-%m');

-- Rental periods per equipment (handover -> return), used for utilization
CREATE VIEW v_rental_periods AS
SELECT e.id AS equipment_id, e.code, e.name, rc.id AS contract_id, rc.contract_no,
       h.handover_at                             AS start_at,
       COALESCE(r.returned_at, NOW())            AS end_at,
       r.rental_amount + COALESCE(r.late_fee,0) + COALESCE(r.overtime_fee,0) AS earned
FROM handovers h
JOIN contract_details cd ON cd.id = h.contract_detail_id
JOIN rental_contracts rc ON rc.id = cd.contract_id
JOIN equipments e        ON e.id = cd.equipment_id
LEFT JOIN equipment_returns r ON r.contract_detail_id = cd.id;

-- Contract list with overdue / due-soon flags
CREATE VIEW v_report_contracts AS
SELECT rc.id, rc.contract_no, cu.name AS customer_name, rc.start_date, rc.end_date,
       rc.pricing_type, rc.total_amount, rc.deposit_amount, rc.status,
       CASE WHEN rc.status = 'ACTIVE' AND rc.end_date < CURDATE()
            THEN DATEDIFF(CURDATE(), rc.end_date) ELSE 0 END           AS overdue_days,
       CASE WHEN rc.status = 'ACTIVE' AND rc.end_date BETWEEN CURDATE() AND CURDATE() + INTERVAL 3 DAY
            THEN 1 ELSE 0 END                                          AS due_soon
FROM rental_contracts rc
JOIN customers cu ON cu.id = rc.customer_id;

-- Receivables and refunds per customer
CREATE VIEW v_report_customer_debt AS
SELECT cu.id AS customer_id, cu.code, cu.name,
       COUNT(DISTINCT s.contract_id)                                               AS settled_contracts,
       SUM(CASE WHEN s.amount_due > 0 THEN s.amount_due - s.paid_amount ELSE 0 END) AS receivable,
       SUM(CASE WHEN s.amount_due < 0 THEN -s.amount_due - s.paid_amount ELSE 0 END) AS refund_pending,
       (SELECT COUNT(*) FROM equipment_returns r
          JOIN contract_details cd ON cd.id = r.contract_detail_id
          JOIN rental_contracts rc2 ON rc2.id = cd.contract_id
         WHERE rc2.customer_id = cu.id AND r.late_days > 0)                       AS late_returns
FROM customers cu
LEFT JOIN rental_contracts rc ON rc.customer_id = cu.id
LEFT JOIN settlements s       ON s.contract_id = rc.id
GROUP BY cu.id, cu.code, cu.name;
